  tools.exec_command({cmd:"curl -sL -w '\\nHTTP:%{http_code}\\n' https://html5up.net/uploads/demos/hyperspace/ -o /tmp/hyper.html; wc -c /tmp/hyper.html",yield_time_ms:20000,max_output_tokens:2000}),
